WITH parsed AS (SELECT id, customer_id, coupon_codes, ship_to, attributes, attributes['utm_source'] AS utm_source, ARRAY_MAX(TRANSFORM(items, i -> i.price)) AS max_item_price, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code, attributes['device'] AS device FROM carts) SELECT CASE WHEN max_item_price >= 190 THEN 'PREMIUM' ELSE 'STANDARD' END AS max_item_price_tier, PERCENTILE_APPROX(max_item_price, 0.95) AS max_item_price_p95, COUNT(*) AS row_count, PERCENTILE_APPROX(max_item_price, 0.5) AS max_item_price_p50, ROUND(AVG(max_item_price), 2) AS avg_max_item_price, APPROX_PERCENTILE(max_item_price, ARRAY(0.25, 0.5, 0.75)) AS max_item_price_quartiles, GROUPING(CASE WHEN max_item_price >= 190 THEN 'PREMIUM' ELSE 'STANDARD' END) AS grouping_id FROM parsed GROUP BY CUBE (CASE WHEN max_item_price >= 190 THEN 'PREMIUM' ELSE 'STANDARD' END) HAVING max_item_price_p50 > 0 ORDER BY max_item_price_tier;
